import re
from ipaddress import IPv6Address, ip_address
from six import u
from taf.cloud.lcmaas.releases.lcmaas_v1 import LCMaaSv1
from taf.cloud.lcmaas.exception import LCMaaSVersionNotSupported


class ConnectionDetails(object):
    def __init__(self, host, username, password, port=8443, secure=True):
        self.protocol = 'https://' if secure else 'http://'
        self.host = host
        self.port = port
        self.username = username
        self.password = password

        self.base_url = '{protocol}{host}:{port}'.format(protocol=self.protocol,
                                                         host=ConnectionDetails.normalize_host_for_base_url(self.host),
                                                         port=self.port)

    @staticmethod
    def normalize_host_for_base_url(host):
        host = host.rstrip("]").lstrip("[")
        try:
            if isinstance(ip_address(u(str(host))), IPv6Address):
                return '[{}]'.format(host)
            else:
                return host
        except (ValueError, TypeError):
            return host

    def make_configuration_host(self, original_endpoint):
        endpoint_match = re.match(r'^https://lcmaas:8443', original_endpoint)
        endpoint = original_endpoint.replace(endpoint_match.group(), '')
        original_endpoint = '{base_url}{endpoint}'.format(base_url=self.base_url,
                                                          endpoint=endpoint)
        return original_endpoint


class SupportedLCMaaS(object):
    lcmaas_v1 = LCMaaSv1


class LCMaaSProvider(object):

    @classmethod
    def create_lcmaas(cls, host, username, password, port=8443, lcmaas_version='lcmaas_v1', secure=True):
        lcmaas_type = getattr(SupportedLCMaaS, lcmaas_version, None)

        if not lcmaas_type:
            exception_message = 'Version {} of lcmaas is not supported'.format(lcmaas_version)
            raise LCMaaSVersionNotSupported(exception_message)

        con_details = ConnectionDetails(
            host=host, port=port, username=username, password=password, secure=secure)
        lcmaas = lcmaas_type(conn_details=con_details)

        return lcmaas
